{
  "purpose": "Coop is a Go command-line tool for developers running coding agents against Git repositories. It runs Claude, Codex, Gemini, and Grok in disposable containers with secrets hidden, and supports interactive work, unattended task queues, isolated forks, editor integration, and remote sessions.",
  "components": [
    {
      "path": "main.go",
      "what_it_does": "Starts the coop CLI through internal/cli."
    },
    {
      "path": "internal/cli",
      "what_it_does": "Defines commands, help, and integration with the execution subsystems."
    },
    {
      "path": "internal/agent",
      "what_it_does": "Holds provider adapters, authentication behavior, native command formats, and locked client dependencies."
    },
    {
      "path": "internal/box",
      "what_it_does": "Builds sandbox images and assembles container execution, secret masking, credentials, and mounts."
    },
    {
      "path": "internal/runtime",
      "what_it_does": "Implements container runtime detection and operations."
    },
    {
      "path": "internal/loop",
      "what_it_does": "Runs unattended task iterations, provider rotation, progress reporting, review, and signoff."
    },
    {
      "path": "internal/tasks",
      "what_it_does": "Manages the folder-based task queue and its lifecycle."
    },
    {
      "path": "internal/forkctl",
      "what_it_does": "Controls isolated fork lifecycle, review, and landing changes."
    },
    {
      "path": "internal/acpproxy",
      "what_it_does": "Maintains editor ACP sessions across provider switches and box restarts."
    },
    {
      "path": "internal/session",
      "what_it_does": "Stores durable remote sessions, operations, turns, and events."
    },
    {
      "path": "internal/sessionsvc",
      "what_it_does": "Exposes the local session service over a Unix socket and manages policy, workspaces, execution, and review."
    },
    {
      "path": "internal/workerconnector",
      "what_it_does": "Connects a worker to an external controller using outbound mutual TLS and durable command receipts."
    },
    {
      "path": "internal/workerproto",
      "what_it_does": "Defines worker protocol messages, checkpoints, storage reporting, and session evidence."
    },
    {
      "path": "internal/networkgateway",
      "what_it_does": "Enforces restricted network access through gateway controller and guard processes."
    },
    {
      "path": "cmd/coop-net",
      "what_it_does": "Provides the executable used inside the trusted gateway image."
    },
    {
      "path": "internal/preset",
      "what_it_does": "Loads orchestration presets and renders provider roles and wrappers."
    },
    {
      "path": "internal/mcp",
      "what_it_does": "Translates shared MCP configuration into provider-native configuration."
    },
    {
      "path": "internal/scaffold",
      "what_it_does": "Embeds the project templates and workflow skills installed by coop init."
    },
    {
      "path": "internal/project",
      "what_it_does": "Reads project configuration, including subprojects and exposed development ports."
    },
    {
      "path": "internal/ui",
      "what_it_does": "Provides terminal formatting, prompts, and live output."
    },
    {
      "path": "docs",
      "what_it_does": "Contains generated CLI and man-page references plus networking and session API documentation."
    },
    {
      "path": "site",
      "what_it_does": "Contains the published static website, documentation, and terminal recordings."
    },
    {
      "path": "brand",
      "what_it_does": "Contains website design guidance and visual specimens; it is not published by the Pages workflow."
    },
    {
      "path": "tools",
      "what_it_does": "Contains documentation generators, repository checks, release validation, benchmarks, and provider qualification tools."
    },
    {
      "path": "testdata/protocol",
      "what_it_does": "Contains worker and workspace checkpoint protocol fixtures."
    },
    {
      "path": ".agent/kb",
      "what_it_does": "Indexes subsystem knowledge and contributor rules used when implementing and reviewing changes."
    },
    {
      "path": ".github/workflows",
      "what_it_does": "Defines CI, tagged binary releases, and website deployment."
    },
    {
      "path": "install.sh",
      "what_it_does": "Downloads and verifies a platform-specific release and installs the coop binary."
    }
  ],
  "build_test_run": [
    {
      "command": "go install honnef.co/go/tools/cmd/staticcheck@\"$(make -s staticcheck-version)\"",
      "source_file": ".github/workflows/ci.yml",
      "what_it_does": "Installs Staticcheck at the version required by the Makefile."
    },
    {
      "command": "go install golang.org/x/vuln/cmd/govulncheck@\"$(make -s govulncheck-version)\"",
      "source_file": ".github/workflows/ci.yml",
      "what_it_does": "Installs the pinned Go vulnerability scanner."
    },
    {
      "command": "make build",
      "source_file": "Makefile",
      "what_it_does": "Builds ./coop with a version derived from Git; the repository pins Go 1.26.6."
    },
    {
      "command": "make install",
      "source_file": "Makefile",
      "what_it_does": "Builds and installs coop into ~/.local/bin."
    },
    {
      "command": "make check",
      "source_file": "Makefile",
      "what_it_does": "Runs the shared local and CI gate: lint, build, vulnerability scan, generated-file checks, tools, unit tests, deterministic process tests, and races. Requires Python 3, ShellCheck, and pinned Go analyzers; no container runtime or credentials."
    },
    {
      "command": "make test",
      "source_file": "Makefile",
      "what_it_does": "Runs all Go unit tests with bounded package parallelism and no container runtime."
    },
    {
      "command": "make race",
      "source_file": "Makefile",
      "what_it_does": "Runs the unit suite under the Go race detector."
    },
    {
      "command": "make lint",
      "source_file": "Makefile",
      "what_it_does": "Checks gofmt and runs vet and pinned Staticcheck for Linux and macOS."
    },
    {
      "command": "make provider-scripted-e2e",
      "source_file": "Makefile",
      "what_it_does": "Tests provider process behavior through deterministic fixtures without credentials or a container runtime."
    },
    {
      "command": "make acp-scripted-e2e",
      "source_file": "Makefile",
      "what_it_does": "Runs deterministic ACP process tests without a runtime or provider credentials."
    },
    {
      "command": "make doctor",
      "source_file": "Makefile",
      "what_it_does": "Builds coop and checks sandbox isolation against a real container runtime."
    },
    {
      "command": "make box-runtime-e2e",
      "source_file": "Makefile",
      "what_it_does": "Tests container process supervision and signal handling; requires COOP_RUNTIME to be set."
    },
    {
      "command": "make review-writes-e2e",
      "source_file": "Makefile",
      "what_it_does": "Tests read-only review mounts against Docker, pulling Alpine if needed."
    },
    {
      "command": "make provider-live-e2e COOP_LIVE_TARGETS='codex,gemini@work'",
      "source_file": "README.md",
      "what_it_does": "Probes selected installed provider CLIs with isolated credentials; requires runtime setup and consumes real provider quota."
    },
    {
      "command": "make provider-qualify",
      "source_file": "Makefile",
      "what_it_does": "Rebuilds images and runs strict live suites to qualify locked clients; requires provider access and consumes quota."
    },
    {
      "command": "make docs",
      "source_file": "Makefile",
      "what_it_does": "Regenerates CLI documentation from internal/cli help definitions."
    },
    {
      "command": "make docs-check",
      "source_file": "Makefile",
      "what_it_does": "Checks that committed generated CLI documentation is current."
    },
    {
      "command": "make casts",
      "source_file": "Makefile",
      "what_it_does": "Regenerates website terminal recordings and checks them for sensitive content."
    },
    {
      "command": "make rules-check",
      "source_file": "Makefile",
      "what_it_does": "Validates knowledge cards and rule references, then checks provider adapter boundaries."
    },
    {
      "command": "make snapshot",
      "source_file": "Makefile",
      "what_it_does": "Builds local release packages using GoReleaser without publishing or signing."
    },
    {
      "command": "coop build && coop doctor",
      "source_file": "README.md",
      "what_it_does": "Builds the sandbox image and verifies isolation after installing coop; requires Docker or supported Apple container."
    },
    {
      "command": "coop claude",
      "source_file": "README.md",
      "what_it_does": "Starts an interactive Claude session in a sandbox for the current repository after authentication and setup."
    },
    {
      "command": "cd site && python3 -m http.server 8000",
      "source_file": "site/README.md",
      "what_it_does": "Previews the static website locally, including fetched terminal recordings."
    }
  ],
  "deploy_release": [
    {
      "step": "Prepare a release on clean, current main with make check passing and real code changes represented in CHANGELOG.md's Unreleased section; optionally validate packaging with make snapshot.",
      "source_file": ".agent/skills/release/SKILL.md"
    },
    {
      "step": "Choose the semantic version, finalize the changelog under a bare version heading, commit it, and create an annotated v-prefixed tag on that commit. Reopen Unreleased in a separate commit.",
      "source_file": ".agent/skills/release/SKILL.md"
    },
    {
      "step": "Obtain explicit confirmation before pushing main and the release tag; the tag push publishes a public release.",
      "source_file": ".agent/skills/release/SKILL.md"
    },
    {
      "step": "A v* tag triggers exact-commit CI qualification, finalized release-note validation, and a remote tag identity check before publication.",
      "source_file": ".github/workflows/release.yml"
    },
    {
      "step": "GoReleaser builds static Linux and macOS binaries for amd64 and arm64, packages documentation and completions, and publishes archives with cosign-signed checksums.",
      "source_file": ".goreleaser.yaml"
    },
    {
      "step": "The release workflow adds build-provenance attestations to the archives; verify the completed workflow and published assets before considering the release shipped.",
      "source_file": ".github/workflows/release.yml"
    },
    {
      "step": "Website changes on main, or a manual workflow dispatch, upload site directly to GitHub Pages with no build step. Repository Pages settings must use GitHub Actions.",
      "source_file": ".github/workflows/pages.yml"
    }
  ],
  "conventions": [
    {
      "rule": "Prefer simple, established designs and match surrounding style; assess product scope, usability, security, and maintainability before coding.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Root-cause bugs before fixing them; do not remove or degrade a feature as a substitute for a fix without approval.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Finish with formatting, a green gate, and failure-path verification; state any checks that could not run.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Read the task queue and knowledge indexes first, then open subsystem cards and rules relevant to the change.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Plan multi-file changes and review substantial work using the repository's workflow skills.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Claim a task before implementation; keep its plan and resume state self-contained, and mark it done only after verification and commit.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Make one commit per implemented task and end its message with a Coop-Task: <id> trailer.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Stay on the assigned branch unless explicitly asked to change it.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Keep writes serialized in a shared checkout; use other agents as read-only advisors unless they have isolated workspaces.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Keep changes on topic; queue separate small fixes and reserve the backlog for large or unscoped work.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Update relevant knowledge cards in the same commit, and turn human corrections into rules checked against sibling code.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Keep long-running output static and bounded, preserve full logs, and retain the command's exit status.",
      "source_file": "AGENTS.md"
    }
  ],
  "where_to_look": [
    {
      "task": "Add or change a CLI command and its generated documentation",
      "path": "internal/cli/help.go"
    },
    {
      "task": "Add a provider or change authentication, command arguments, or resume behavior",
      "path": "internal/agent"
    },
    {
      "task": "Update bundled provider client versions",
      "path": "internal/agent/locked-clients/package.json"
    },
    {
      "task": "Change sandbox mounts, secret masking, or image construction",
      "path": "internal/box"
    },
    {
      "task": "Change unattended task execution or review behavior",
      "path": "internal/loop"
    },
    {
      "task": "Change task queue operations",
      "path": "internal/tasks"
    },
    {
      "task": "Change fork review or merging",
      "path": "internal/forkctl"
    },
    {
      "task": "Debug editor session switching and recovery",
      "path": "internal/acpproxy"
    },
    {
      "task": "Integrate with the session service or remote worker",
      "path": "docs/session-api.md"
    },
    {
      "task": "Understand filtered network setup and supported rules",
      "path": "docs/networking.md"
    },
    {
      "task": "Change the files generated by coop init",
      "path": "internal/scaffold/templates"
    },
    {
      "task": "Add a check to the shared contributor and CI gate",
      "path": "Makefile"
    },
    {
      "task": "Find deterministic provider test contracts",
      "path": ".agent/kb/provider-scripted-e2e.md"
    },
    {
      "task": "Edit the published website",
      "path": "site/README.md"
    },
    {
      "task": "Find website design guidance before changing its appearance",
      "path": "brand/DESIGN.md"
    },
    {
      "task": "Prepare and publish a binary release",
      "path": ".agent/skills/release/SKILL.md"
    }
  ],
  "open_questions": [
    "The provider qualification knowledge card records unresolved live-suite gaps and no enforced qualification record. Confirm the accepted qualification evidence before updating bundled client versions."
  ]
}
